await Denied(()=>u.Store.RecordManualQuoteSend(u.Id,uc.Id,send with{PdfHash=new string('0',64)},ray),"Different PDF hash rejected before record write");
await Denied(()=>u.Store.RecordManualQuoteSend(u.Id,uc.Id,send with{SentAtUtc=DateTimeOffset.UtcNow.AddDays(1)},ray),"Future send time rejected; no scheduling implied");
await Denied(()=>u.Store.RecordManualQuoteSend(u.Id,uc.Id,send with{Recipient=new string('r',301)},ray),"Overlong recipient input rejected");
